"use strict";(globalThis.webpackChunkgrc||=[]).push([[74221],{23786(e){e.exports=JSON.parse('{"citeKey":"lee2023datalifecycles","slug":"lee-2023-data-lifecycles-c393","title":"Data Flow Lifecycles for Optimizing Workflow Coordination","authors":["H. Lee","L. Guo","M. Tang","J. Firoz","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'23), November 12-17, 2023","type":"Conference","entryType":"inproceedings","date":"November, 2023","year":2023,"era":"iit","month":11,"doi":"10.1145/3581784.3607104","abstract":"A critical performance challenge in distributed scientific workflows is coordinating tasks and data flows on distributed resources. To guide these decisions, this paper introduces data flow lifecycle anal- ysis. Workflows are commonly represented using directed acyclic graphs (DAGs). Data flow lifecycles (DFL) enrich task DAGs with data objects and properties that describe data flow and how tasks interact with that flow. Lifecycles enable analysis from several important perspectives: task, data, and data flow. We describe rep- resentation, measurement, analysis, visualization, and opportunity identification for DFLs. Our measurement is both distributed and scalable, using space that is constant per data file. We use lifecycles and opportunity analysis to reason about improved task placement and reduced data movement for five scientific workflows with dif- ferent characteristics. Case studies show improvements of 15x, 1.9\xd7, and 10-30x. Our work is implemented in the DataLife tool.","hasAbstract":true,"lede":"To guide these decisions, this paper introduces data flow lifecycle anal- ysis.","pages":"1\u201315","links":{"pdf":"https://grc.iit.edu/papers/2023/lee-2023-data-lifecycles-c393.pdf"},"tags":["Data Analytics","Performance Measurement","Modeling","Tools"],"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["iowarp","portus"],"memberAuthors":["guo-luanzheng","tang-meng","tallent-nathan","kougkas-anthony","sun-xian-he"],"funding":[{"agency":"PNNL","award":"DE-AC05-76RL01830"}]}')}}]);